mapper.update:
update sdsshop.u_m_batchinfo
   set goodsname = #{goodsName},
       spec = #{spec, jdbcType=VARCHAR},
       unit = #{unit, jdbcType=VARCHAR},
       warename = #{wareName},
       purchaseprice = case
           when (remainingqty + #{remainQty}) > 0
           then (coalesce(purchaseprice, 0) * remainingqty
                 + coalesce(#{purchaseAmount, jdbcType=DECIMAL}, 0))
                / (remainingqty + #{remainQty})
           else coalesce(#{costPrice, jdbcType=DECIMAL}, purchaseprice)
       end,
       purchaseamount = purchaseamount + coalesce(#{purchaseAmount, jdbcType=DECIMAL}, 0),
       initialqty = initialqty + #{initQty},
       remainingqty = remainingqty + #{remainQty},
       closedflag = 0
 where shop_code = #{shopCode} and batchcode = #{batchCode}
   and goodscode = #{goodsCode} and warecode = #{wareCode}
   and qualityflag = #{qualityFlag}
   and onhandflag = #{onhandFlag}

update sdsshop.u_m_batchinfo
   set goodsname = #{goodsName}, warename = #{wareName},
       initialqty = #{initQty}, remainingqty = #{remainQty},
       purchaseprice = #{costPrice}, productiondate = #{productDate},
       expiredate = #{expireDate}, closedflag = case when #{status} = 'active' then 0 else 1 end
 where shop_code = #{shopCode} and batchcode = #{batchCode}
   and goodscode = #{goodsCode} and warecode = #{wareCode}
   and qualityflag = #{qualityFlag}
   and onhandflag = #{onhandFlag}

update sdsshop.u_m_batchinfo set position = #{position, jdbcType=VARCHAR}
 where shop_code = #{shopCode} and batchcode = #{batchCode}
   and goodscode = #{goodsCode} and warecode = #{wareCode}
   and qualityflag = #{state.qualityFlag}
   and onhandflag = #{state.onhandFlag}

update sdsshop.u_m_batchinfo set remainingqty = remainingqty - #{deductQty}
 where shop_code = #{shopCode} and batchcode = #{batchCode}
   and goodscode = #{goodsCode} and warecode = #{wareCode}
   and qualityflag = #{state.qualityFlag}
   and onhandflag = #{state.onhandFlag}
   and closedflag = 0 and remainingqty >= #{deductQty}

update sdsshop.u_m_batchinfo set purchaseprice = #{costPrice}, purchaseamount = #{purchaseAmount}
 where shop_code = #{shopCode} and batchcode = #{batchCode}
   and goodscode = #{goodsCode} and warecode = #{wareCode}
   and qualityflag = #{state.qualityFlag}
   and onhandflag = #{state.onhandFlag}
   and closedflag = 0

